Write httptest-based tests for this Go handler. It calls an external weather API and returns the current temperature:

```go
func GetTemperature(client *http.Client, baseURL string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		city := r.URL.Query().Get("city")
		if city == "" {
			http.Error(w, "city is required", http.StatusBadRequest)
			return
		}
		resp, err := client.Get(baseURL + "/v1/weather?city=" + city)
		if err != nil || resp.StatusCode != http.StatusOK {
			http.Error(w, "upstream error", http.StatusBadGateway)
			return
		}
		defer resp.Body.Close()
		var data struct{ TempC float64 `json:"temp_c"` }
		json.NewDecoder(resp.Body).Decode(&data)
		json.NewEncoder(w).Encode(map[string]float64{"temp_c": data.TempC})
	}
}
```

Write tests for this handler, which depends on an internal service interface, not an HTTP client:

```go
type UserStore interface {
	Create(ctx context.Context, u User) (User, error)
}

func CreateUser(store UserStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var u User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil || u.Email == "" {
			http.Error(w, "invalid body", http.StatusBadRequest)
			return
		}
		created, err := store.Create(r.Context(), u)
		if err != nil {
			http.Error(w, "could not create user", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(created)
	}
}
```

Write tests for this rate-limiting middleware:

```go
func RateLimit(limiter *Limiter) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if !limiter.Allow(r.RemoteAddr) {
				http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}
```

